css:
:host {
  --bg-top: #0d3257;
  --bg-mid: #214463;
  --bg-bottom: #eee4d1;
  --sand: rgba(245, 236, 219, 0.96);
  --sand-strong: #f6ead4;
  --ink: #143254;
  --teal: #18b7b7;
  --gold: #c79a3e;
  --copper: #b56404;
  --mist: #dce8ee;
  --forest: #237a57;
  --orange: #ff9f43;
  --shadow: 0 18px 40px rgba(8, 18, 31, 0.18);
}

/* Expand calendar controls into the free schedule space for easier tapping. */
.schedule-card .date-field input,
.schedule-card .soft-button,
.schedule-card .primary-button {
  min-height: 58px;
  padding-top: 13px;
  padding-bottom: 13px;
}

.schedule-card .quick-actions {
  gap: 8px;
}

/* Subtle rings make date navigation easier to identify and tap. */
.schedule-card .date-field input,
.schedule-card #prevButton,
.schedule-card #nextButton {
  border: 2px solid rgba(23, 98, 161, 0.24);
  box-shadow: 0 0 0 3px rgba(219, 241, 255, 0.44), 0 8px 16px rgba(23, 98, 161, 0.12), inset 0 1px 0 rgba(255, 255, 255, 0.78);
}

.schedule-card .date-field input {
  width: calc(100% - 4px);
  justify-self: center;
  box-sizing: border-box;
  border: 2px solid rgba(23, 98, 161, 0.56) !important;
  border-radius: 12px;
  outline: 1px solid rgba(255, 255, 255, 0.72);
}

.schedule-card .date-field input:focus,
.schedule-card #prevButton:focus-visible,
.schedule-card #nextButton:focus-visible {
  outline: 0;
  border-color: rgba(23, 98, 161, 0.52);
  box-shadow: 0 0 0 4px rgba(147, 197, 253, 0.38), 0 10px 18px rgba(23, 98, 161, 0.16), inset 0 1px 0 rgba(255, 255, 255, 0.88);
}

/* Final title-logo treatment: a visible iPhone-style 3D button. */
.premium-title-logo {
  position: relative;
  pointer-events: none;
  cursor: default;
  isolation: isolate;
  overflow: hidden;
  border: 2px solid rgba(255, 255, 255, 0.96) !important;
  background: linear-gradient(145deg, #ffffff 0%, #e9f5fb 48%, #a8c7d6 100%) !important;
  box-shadow: 0 0 0 3px rgba(116, 190, 226, 0.28), 0 18px 30px rgba(8, 35, 55, 0.34), inset 0 3px 0 rgba(255, 255, 255, 0.98), inset 0 -10px 16px rgba(33, 77, 101, 0.22) !important;
  transition: transform 160ms ease, filter 160ms ease, box-shadow 160ms ease;
}

.premium-title-logo::before {
  content: "";
  position: absolute;
  z-index: -1;
  inset: -38% -24% auto;
  height: 66%;
  border-radius: 50%;
  background: linear-gradient(105deg, transparent 16%, rgba(255, 255, 255, 0.94) 50%, transparent 84%);
  transform: rotate(-9deg);
  pointer-events: none;
}

.premium-title-logo:hover,
.premium-title-logo:focus-visible {
  filter: saturate(1.12) brightness(1.04);
  transform: translateY(-3px) scale(1.025);
  box-shadow: 0 0 0 4px rgba(116, 190, 226, 0.42), 0 24px 38px rgba(8, 35, 55, 0.38), inset 0 3px 0 rgba(255, 255, 255, 1), inset 0 -10px 16px rgba(33, 77, 101, 0.16) !important;
}

.premium-title-logo:active {
  transform: translateY(2px) scale(0.975);
  box-shadow: 0 0 0 3px rgba(116, 190, 226, 0.34), 0 8px 13px rgba(8, 35, 55, 0.24), inset 0 4px 8px rgba(33, 77, 101, 0.24) !important;
}

.premium-title-logo > img {
  position: relative;
  z-index: 1;
  filter: drop-shadow(0 9px 10px rgba(12, 43, 62, 0.28));
}

* {
  box-sizing: border-box;
}

:host,[data-module-body] {
  width: 100%;
  height: 100%;
  max-width: 100%;
  overflow: hidden;
  overscroll-behavior: none;
}

[data-module-body] {
  margin: 0;
  font-family: "Manrope", sans-serif;
  font-size: 110%;
  background:
    radial-gradient(circle at top right, rgba(255, 255, 255, 0.12), transparent 22%),
    radial-gradient(circle at left 80%, rgba(255, 183, 77, 0.12), transparent 18%),
    linear-gradient(180deg, var(--bg-top) 0%, var(--bg-mid) 44%, var(--bg-bottom) 100%);
  color: var(--ink);
}

[data-module-body].modal-open {
  overflow: hidden;
}

.page-shell {
  height: 100dvh;
  min-height: 0;
  overflow: hidden;
  display: grid;
  justify-items: center;
  align-content: start;
  padding:
    max(12px, env(safe-area-inset-top, 0px))
    max(12px, env(safe-area-inset-right, 0px))
    max(12px, env(safe-area-inset-bottom, 0px))
    max(12px, env(safe-area-inset-left, 0px));
}

.app-frame {
  width: min(100%, 430px);
  min-width: 0;
  margin: 0 auto;
  display: grid;
  gap: 8px;
  transform: scale(var(--app-scale, 1));
  transform-origin: top center;
  will-change: transform;
}

.hero-card,
.panel-card,
.footer-banner {
  border-radius: 24px;
  box-shadow: var(--shadow);
}

.hero-card {
  display: flex;
  align-items: center;
  min-width: 0;
  gap: 14px;
  padding: 24px 18px;
  background: linear-gradient(90deg, rgba(255, 210, 120, 0.4) 0%, rgba(232, 217, 187, 0.96) 100%);
  border: 2px solid rgba(255, 159, 67, 0.72);
  box-shadow: 0 22px 40px rgba(181, 100, 4, 0.22);
}

.hero-side-icon {
  position: relative;
  margin-left: auto;
  width: 112px;
  height: 112px;
  border-radius: 24px;
  background: rgba(255, 255, 255, 0.92);
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  box-shadow: 0 12px 24px rgba(8, 18, 31, 0.12);
  text-decoration: none;
}

.hero-side-icon:hover {
  transform: translateY(-1px) scale(1.02);
}

.hero-side-icon__image {
  width: 98px;
  height: 98px;
  object-fit: contain;
}

.operational-logo-label {
  position: absolute;
  z-index: 2;
  right: 7px;
  bottom: 4px;
  left: 7px;
  padding: 2px 4px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.92);
  color: #1762a1;
  font-size: 0.58rem;
  font-weight: 900;
  letter-spacing: 0.08em;
  line-height: 1.1;
  text-align: center;
}

.hero-logo-wrap {
  width: 118px;
  height: 118px;
  border-radius: 24px;
  background: rgba(255, 255, 255, 0.94);
  display: grid;
  place-items: center;
  flex: 0 0 auto;
}

.hero-logo-link {
  text-decoration: none;
}

.hero-logo-link:hover {
  transform: translateY(-1px) scale(1.01);
  box-shadow: 0 14px 28px rgba(8, 18, 31, 0.16);
}

.hero-logo {
  width: 104px;
  height: 104px;
  object-fit: contain;
}

/* Premium 3D logo button for the title. */
.hero-logo-wrap {
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.95);
  background: linear-gradient(145deg, #ffffff 0%, #e8f2f7 52%, #b9d0dc 100%);
  box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.48), 0 16px 28px rgba(12, 49, 72, 0.26), inset 0 2px 0 rgba(255, 255, 255, 0.98), inset 0 -8px 14px rgba(37, 78, 101, 0.14);
  transition: transform 160ms ease, filter 160ms ease, box-shadow 160ms ease;
}

.hero-logo-wrap:hover,
.hero-logo-wrap:focus-visible {
  filter: saturate(1.08);
  transform: translateY(-2px) scale(1.015);
  box-shadow: 0 0 0 3px rgba(219, 241, 255, 0.88), 0 20px 34px rgba(12, 49, 72, 0.3), inset 0 2px 0 rgba(255, 255, 255, 1), inset 0 -8px 14px rgba(37, 78, 101, 0.1);
}

.hero-logo-wrap:active {
  transform: translateY(1px) scale(0.98);
  box-shadow: 0 0 0 3px rgba(191, 219, 254, 0.86), 0 8px 14px rgba(12, 49, 72, 0.2), inset 0 3px 7px rgba(37, 78, 101, 0.16);
}

.hero-logo {
  position: relative;
  z-index: 1;
  filter: drop-shadow(0 8px 9px rgba(20, 52, 75, 0.2));
}

.hero-copy {
  min-width: 0;
  flex: 1 1 auto;
  text-align: center;
}

.hero-kicker {
  display: block;
  font-size: 1rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  color: rgba(125, 77, 10, 0.96);
  text-transform: uppercase;
}

.hero-copy h1 {
  margin: 2px 0 0;
  font-size: clamp(2.1rem, 7vw, 2.9rem);
  line-height: 0.9;
  font-weight: 900;
  letter-spacing: 0.08em;
  color: var(--copper);
  text-shadow: 5px 5px 10px rgba(122, 57, 0, 0.34);
}

.panel-card {
  background: var(--sand);
  border: 1px solid rgba(255, 255, 255, 0.18);
  padding: 10px;
}

.schedule-card {
  border-color: rgba(199, 154, 62, 0.46);
}

.search-banner {
  margin-bottom: 8px;
  padding: 8px;
  border-radius: 18px;
  background: rgba(220, 232, 238, 0.34);
  border: 1px solid rgba(13, 50, 87, 0.08);
}

.card-header,
.schedule-top,
.badge-row,
.quick-actions {
  display: flex;
  gap: 6px;
}

.card-header,
.schedule-top {
  justify-content: space-between;
  align-items: flex-start;
}

.search-banner .card-header {
  display: block;
  position: relative;
  width: 100%;
  text-align: center;
}

.search-banner .card-title {
  width: 100%;
  text-align: center;
}

.card-title,
.eyebrow,
.sub-banner-title {
  margin: 0;
  font-weight: 700;
}

.card-title {
  font-size: 0.7rem;
}

.range-label,
.eyebrow {
  margin: 0;
  font-size: 0.53rem;
  color: rgba(20, 50, 84, 0.72);
}

.controls-grid {
  display: grid;
  gap: 5px;
  margin-top: 6px;
}

.install-banner {
  width: 100%;
  padding: 8px 10px;
  background: linear-gradient(90deg, #0d3257 0%, #1762a1 100%);
  color: #fff;
  text-align: center;
  box-shadow: 0 12px 24px rgba(13, 50, 87, 0.18);
  font-size: 0.6rem;
}

.install-banner:hover {
  opacity: 0.96;
}

.date-field {
  display: grid;
  min-width: 0;
  gap: 4px;
  overflow: hidden;
  border-radius: 12px;
  font-size: 0.55rem;
  font-weight: 700;
}

.date-field input {
  width: 100%;
  border: 0;
  border-radius: 12px;
  min-height: 48px;
  padding: 12px 10px;
  background: var(--mist);
  font: inherit;
  color: var(--ink);
  text-align: center;
}

.date-field input::-webkit-datetime-edit {
  text-align: center;
}

.quick-actions {
  flex-wrap: nowrap;
  align-items: stretch;
  justify-content: space-between;
}

button,
.site-banner {
  border: 0;
  border-radius: 14px;
  font: inherit;
  font-weight: 800;
  cursor: pointer;
  transition: transform 140ms ease, opacity 140ms ease, box-shadow 140ms ease;
}

button:hover,
.site-banner:hover {
  transform: translateY(-1px);
}

.soft-button,
.primary-button {
  flex: 1 1 0;
  min-width: 0;
  min-height: 48px;
  padding: 10px 8px;
  font-size: 0.66rem;
  line-height: 1.05;
  text-align: center;
}

#todayButton {
  white-space: pre-line;
  line-height: 1.05;
}

.soft-button {
  background: var(--mist);
  color: var(--ink);
}

.primary-button {
  background: var(--bg-top);
  color: #fff;
}

.notice,
.empty-state,
.sub-banner {
  border-radius: 14px;
  padding: 8px 10px;
}

.notice {
  margin-top: 8px;
  background: rgba(255, 159, 67, 0.16);
  font-size: 0.56rem;
  font-weight: 600;
}

.date-title {
  margin: 4px 0 0;
  font-size: clamp(0.9rem, 3.3vw, 1.08rem);
  line-height: 1.15;
}

.today-badge,
.capsule {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 5px 9px;
  border-radius: 999px;
  font-size: 0.5rem;
  font-weight: 800;
}

.today-badge {
  background: rgba(199, 154, 62, 0.24);
  color: var(--copper);
}

.badge-row {
  flex-wrap: wrap;
  margin-top: 8px;
}

.capsule-green {
  background: rgba(35, 122, 87, 0.14);
  color: var(--forest);
}

.capsule-blue {
  background: var(--mist);
  color: var(--bg-top);
}

.siglas-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(62px, 1fr));
  gap: 6px;
  margin-top: 8px;
}

.sigla-item {
  display: grid;
  justify-items: center;
  gap: 3px;
}

.sigla-token {
  position: relative;
  width: 100%;
  min-height: 30px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 14px;
  padding: 4px 4px;
  font-size: 0.79rem;
  font-weight: 800;
  text-align: center;
  color: #111111;
  white-space: nowrap;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.98) 0%, rgba(240, 240, 240, 0.96) 100%);
  border: 1px solid rgba(24, 24, 24, 0.24);
  box-shadow:
    0 0 0 1px rgba(255, 255, 255, 0.82),
    0 10px 20px rgba(0, 0, 0, 0.08),
    0 0 16px rgba(0, 0, 0, 0.12),
    inset 0 1px 0 rgba(255, 255, 255, 0.92);
}

.sigla-button {
  cursor: pointer;
  touch-action: manipulation;
  -webkit-touch-callout: none;
  user-select: none;
  transition: transform 140ms ease, box-shadow 180ms ease, border-color 180ms ease;
}

.sigla-button--pressing {
  transform: scale(0.94);
  box-shadow:
    0 0 0 3px rgba(59, 130, 246, 0.26),
    0 0 18px rgba(59, 130, 246, 0.44),
    inset 0 0 12px rgba(255, 255, 255, 0.5);
}

.sigla-button:hover {
  transform: translateY(-1px);
  box-shadow:
    0 0 0 1px rgba(255, 255, 255, 0.86),
    0 12px 24px rgba(0, 0, 0, 0.1),
    0 0 18px rgba(0, 0, 0, 0.16),
    inset 0 1px 0 rgba(255, 255, 255, 0.94);
}

.sigla-token--checked::before,
.sigla-token--checked::after {
  content: none;
}

.sigla-token--vacation {
  color: #17833c !important;
  background:
    radial-gradient(circle at center, rgba(255, 252, 219, 1) 0%, rgba(254, 249, 169, 0.98) 34%, rgba(253, 230, 138, 0.98) 62%, rgba(251, 191, 36, 0.92) 100%) !important;
  border-color: rgba(234, 179, 8, 0.92) !important;
  border-radius: 999px !important;
  text-shadow: 0 1px 2px rgba(5, 61, 27, 0.42), 0 0 4px rgba(74, 222, 128, 0.48);
  font-size: 0.79rem !important;
  box-shadow:
    0 0 0 2px rgba(254, 243, 199, 0.98),
    0 0 0 4px rgba(253, 230, 138, 0.34),
    0 0 13px rgba(252, 211, 77, 0.58),
    inset 0 0 10px rgba(255, 255, 255, 0.34),
    0 6px 14px rgba(217, 119, 6, 0.14) !important;
}

.sigla-token--checked {
  color: #ffffff !important;
  background: linear-gradient(180deg, rgba(134, 239, 172, 0.98) 0%, rgba(74, 222, 128, 0.96) 42%, rgba(34, 197, 94, 0.94) 100%) !important;
  border-color: rgba(34, 197, 94, 0.88) !important;
  text-shadow: 0 1px 1px rgba(0, 0, 0, 0.22);
  box-shadow:
    0 0 0 2px rgba(220, 252, 231, 0.96),
    0 0 10px rgba(74, 222, 128, 0.34),
    inset 0 0 12px rgba(255, 255, 255, 0.18),
    0 8px 18px rgba(21, 128, 61, 0.16) !important;
}

.offline-sigla {
  color: #8f3f3f;
  border-color: rgba(185, 92, 92, 0.48);
  background: linear-gradient(180deg, rgba(255, 244, 244, 0.98) 0%, rgba(246, 218, 218, 0.96) 100%);
  box-shadow:
    0 0 0 1px rgba(255, 255, 255, 0.82),
    0 8px 16px rgba(143, 63, 63, 0.1),
    inset 0 1px 0 rgba(255, 255, 255, 0.92);
}

.offline-sigla:hover,
.offline-sigla:focus-visible {
  color: #7f3030;
  border-color: rgba(167, 63, 63, 0.62);
  box-shadow:
    0 0 0 1px rgba(255, 255, 255, 0.86),
    0 10px 20px rgba(143, 63, 63, 0.16),
    inset 0 1px 0 rgba(255, 255, 255, 0.94);
}

.sigla-index {
  font-size: 0.58rem;
  font-weight: 700;
  color: #000;
}

.vacation-banner {
  margin-top: 8px;
  background: rgba(199, 154, 62, 0.18);
  border: 1px solid rgba(199, 154, 62, 0.35);
}

.sub-banner-title {
  font-size: 0.64rem;
}

.sub-banner-text {
  margin: 4px 0 0;
  font-size: 0.6rem;
  font-weight: 700;
}

.vacation-banner__actions {
  display: flex;
  align-items: center;
  gap: 7px;
}

.vacation-file-link {
  display: inline-flex;
  flex: 1 1 0;
  min-width: 0;
  align-items: center;
  justify-content: center;
  min-height: 38px;
  padding: 7px 8px;
  border: 1px solid rgba(147, 197, 253, 0.95);
  border-radius: 13px;
  background: linear-gradient(180deg, #76a9ee 0%, #4e84cf 100%);
  box-shadow: 0 0 0 2px rgba(191, 219, 254, 0.62), 0 0 12px rgba(96, 165, 250, 0.42), inset 0 1px 0 rgba(255, 255, 255, 0.34), 0 6px 12px rgba(30, 64, 175, 0.16);
  color: #f8fbff;
  font-size: 0.66rem;
  font-weight: 900;
  letter-spacing: 0.02em;
  line-height: 1;
  text-decoration: none;
  white-space: nowrap;
}

.vacation-file-link:active {
  transform: scale(0.97);
}

.vacation-file-link--scale {
  gap: 0;
  overflow: hidden;
  border-color: rgba(224, 183, 54, 0.72);
  background: linear-gradient(105deg, #ffffff 0%, #f7f5ee 47%, #fff6bd 53%, #f9d75c 100%);
  box-shadow: 0 0 0 2px rgba(255, 248, 207, 0.84), 0 0 12px rgba(250, 204, 21, 0.28), inset 0 1px 0 rgba(255, 255, 255, 0.9), 0 6px 12px rgba(161, 98, 7, 0.13);
}

.vacation-file-link__scale {
  color: #171717;
  text-shadow: 0 1px 0 rgba(255, 255, 255, 0.95);
}

.vacation-file-link__vacation {
  color: #7a4a00;
  text-shadow: 0 1px 0 rgba(255, 255, 255, 0.58);
}

.vacation-file-link--labels {
  border-color: rgba(147, 197, 253, 0.9);
  background: linear-gradient(180deg, #72a7ea 0%, #4d82cc 100%);
  color: #ffffff;
  text-shadow: 0 1px 1px rgba(14, 48, 92, 0.38);
}

.dc-vacation-sigla {
  display: inline-block;
  margin: 0;
  padding: 1px 3px;
  border: 1px solid rgba(234, 179, 8, 0.92);
  border-radius: 999px;
  background: radial-gradient(circle at center, #fffddb 0%, #fef9a9 36%, #fde68a 66%, #fbbf24 100%);
  box-shadow: 0 0 0 1px rgba(254, 243, 199, 0.96), 0 0 0 2px rgba(253, 230, 138, 0.34), 0 0 7px rgba(252, 211, 77, 0.46), inset 0 0 5px rgba(255, 255, 255, 0.42);
  color: #17833c;
  font-size: 0.82em;
  font-weight: 900;
  text-shadow: 0 1px 2px rgba(5, 61, 27, 0.42), 0 0 4px rgba(74, 222, 128, 0.48);
}

.sigla-token__vacation-part {
  display: inline-block;
  margin: 0;
  padding: 1px 3px;
  border: 1px solid rgba(234, 179, 8, 0.92);
  border-radius: 999px;
  background: radial-gradient(circle at center, #fffddb 0%, #fef9a9 36%, #fde68a 66%, #fbbf24 100%);
  box-shadow: 0 0 0 1px rgba(254, 243, 199, 0.96), 0 0 0 2px rgba(253, 230, 138, 0.34), 0 0 7px rgba(252, 211, 77, 0.46), inset 0 0 5px rgba(255, 255, 255, 0.42);
  color: #17833c;
  font-size: 0.82em;
  font-weight: 900;
  text-shadow: 0 1px 2px rgba(5, 61, 27, 0.42), 0 0 4px rgba(74, 222, 128, 0.48);
}

.sigla-token__part {
  display: inline-flex;
  align-items: center;
  padding: 0 2px 2px 1px;
}

.sigla-token__vacation-wrap {
  position: relative;
  display: inline-flex;
  align-items: center;
}

.sigla-token__vacation-label {
  display: inline-flex;
  align-items: center;
}

.sigla-token__position {
  position: absolute;
  right: -4px;
  bottom: -5px;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 8px;
  height: 8px;
  border: 1px solid rgba(9, 45, 68, 0.36);
  border-radius: 50%;
  background: #f9fbfc;
  box-shadow: 0 1px 2px rgba(8, 36, 58, 0.2);
  color: #0b4569;
  font-size: 0.31rem;
  font-weight: 900;
  line-height: 1;
}

.vacation-sigla {
  margin: 0 4px 4px 0;
  padding: 4px 8px;
  border: 0;
  border-radius: 999px;
  background: rgba(13, 50, 87, 0.12);
  color: var(--bg-top);
  font-size: 0.58rem;
  font-weight: 800;
  cursor: pointer;
}

.site-banner {
  position: relative;
  isolation: isolate;
  display: grid;
  place-items: center;
  overflow: hidden;
  margin-top: 0;
  min-height: 118px;
  padding: 30px 18px;
  text-align: center;
  text-decoration: none;
  font-size: clamp(2rem, 7.2vw, 2.8rem);
  font-weight: 900;
  letter-spacing: 0.1em;
  line-height: 1.05;
  color: #fffdf4;
  background:
    radial-gradient(circle at 18% 12%, rgba(104, 231, 209, 0.42), transparent 31%),
